package io.forgeloop.control.domain;
import jakarta.persistence.*; import java.time.Instant; import java.util.*;
@Entity public class FeatureRun { @Id @GeneratedValue(strategy=GenerationType.UUID) private String id; private String repository; private String sourceRef; private String title; @Column(length=20000) private String specification; private double budgetUsd; private String harnessProfile; private int policyRevision; @Enumerated(EnumType.STRING) private RunState state; private Instant createdAt; @OneToMany(mappedBy="run",cascade=CascadeType.ALL,orphanRemoval=true) private List<DeliveryTask> tasks=new ArrayList<>(); @OneToMany(mappedBy="run",cascade=CascadeType.ALL,orphanRemoval=true) private List<VerificationGate> gates=new ArrayList<>(); @OneToMany(mappedBy="run",cascade=CascadeType.ALL,orphanRemoval=true) private List<AcceptanceCriterion> criteria=new ArrayList<>(); protected FeatureRun(){} public FeatureRun(String repository,String sourceRef,String title,String specification,double budgetUsd,String harnessProfile,int policyRevision){this.repository=repository;this.sourceRef=sourceRef;this.title=title;this.specification=specification;this.budgetUsd=budgetUsd;this.harnessProfile=harnessProfile;this.policyRevision=policyRevision;this.state=RunState.RECEIVED;this.createdAt=Instant.now();} public void addTask(String role,String title,String requiredCapability){tasks.add(new DeliveryTask(this,role,title,requiredCapability));} public void addGate(String name){gates.add(new VerificationGate(this,name));} public void addCriterion(String statement){criteria.add(new AcceptanceCriterion(this,statement));} public String getId(){return id;} public String getRepository(){return repository;} public String getSourceRef(){return sourceRef;} public String getTitle(){return title;} public String getSpecification(){return specification;} public double getBudgetUsd(){return budgetUsd;} public String getHarnessProfile(){return harnessProfile;} public int getPolicyRevision(){return policyRevision;} public RunState getState(){return state;} public String getCreatedAt(){return createdAt.toString();} public List<DeliveryTask> getTasks(){return List.copyOf(tasks);} public List<VerificationGate> getGates(){return List.copyOf(gates);} public List<AcceptanceCriterion> getCriteria(){return List.copyOf(criteria);} }
